-- The `pg_attribute` columns pglet models. `atttypmod` is the same fact the
-- `RowDescription` carries (a `varchar(8)` is 12, a `numeric(10,2)` is 655366);
-- `attidentity` is `a` / `d` / the **empty** `"char"`, which is a different byte from the
-- space a non-FK `confdeltype` holds; `atthasdef` is false for an identity column even
-- though the engine resolves its value from a sequence.
-- An enum column reports its enum type's OID and 18.6's `typlen` of 4, so
-- `pg_attribute ⨝ pg_type` lands on the enum row rather than on `text`.
-- @setup
CREATE TYPE cat_mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE cat_parent (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  region VARCHAR(8) NOT NULL,
  CONSTRAINT cat_parent_code_region_uq UNIQUE (code, region)
);
CREATE TABLE cat_child (
  cid INT GENERATED BY DEFAULT AS IDENTITY,
  pid INT REFERENCES cat_parent(id) ON DELETE CASCADE,
  qty INT NOT NULL,
  label TEXT,
  price NUMERIC(10,2),
  m cat_mood,
  CONSTRAINT cat_child_qty_positive CHECK (qty > 0),
  -- Two columns, named out of position order: `conkey` is 18.6's `pull_var_clause`
  -- walk order (`{3,2}`), not the table's column order. Integer operands only —
  -- a text literal would drag in the deparser's recorded `''` vs `''::text`
  -- divergence, which is not this constraint's subject.
  CONSTRAINT cat_child_qty_pid CHECK (qty > 1 AND pid > 0)
);
CREATE INDEX cat_child_pid_idx ON cat_child (pid);
CREATE INDEX cat_child_lower_label_idx ON cat_child (lower(label));
CREATE INDEX cat_child_partial_idx ON cat_child (qty) WHERE qty > 10;
CREATE SEQUENCE cat_plain_seq START 5;

-- @test
SELECT c.relname::text AS tbl, a.attname::text AS attname, a.attlen, a.attnum,
       a.atttypmod, a.attndims, a.attnotnull, a.atthasdef,
       a.attidentity::text AS attidentity, a.attgenerated::text AS attgenerated,
       a.attisdropped, t.typname::text AS typname
FROM pg_attribute a
JOIN pg_class c ON c.oid = a.attrelid
JOIN pg_type t ON t.oid = a.atttypid
WHERE c.relname::text IN ('cat_parent', 'cat_child') AND a.attnum > 0
ORDER BY c.relname::text, a.attnum
